begin;

-- The 93 lessons of מועדון החטובים, imported from the school that hosts them.
--
-- Each lesson keeps its own place: `sort_order` is the lesson's sequence inside
-- its course, and `description` carries the chapter it belongs to, so the course
-- screen can group them the way the school does. Nothing here is authored - the
-- titles, the order, the videos, the PDFs and the chapters are all Eli's, read
-- straight off the source. Lessons that are empty on the source are left out
-- rather than published as blank rows.
--
-- Media is one of three kinds, and the lesson screen tells them apart by URL:
--   YouTube  - embedded and played in place;
--   Instagram - embedded as a reel;
--   a PDF or an outside link - opened out of the app.
--
-- Re-running this replaces the imported rows in place: the ids are derived from
-- the source lesson, so an import never duplicates a lesson, and a client's
-- progress and favourites - which point at these ids - survive it.
insert into public.content_items(
  id, title, description, category_id, category, content_type, thumbnail_url,
  body, media_url, published, status, sort_order, created_by, estimated_minutes
)
